E("s9f-u2-cr-atom-model", 2, ["SC9.4.2"], 3, "var", varset([
  function () { return textq("Dessine en mots le modèle de Bohr d'un atome de lithium (3 protons, 4 neutrons) : décris le noyau, puis la répartition des électrons sur les niveaux d'énergie, et nomme UNE limite de ce modèle. (3 points)", ["noyau : 3 protons et 4 neutrons au centre", "électrons : 3 au total, 2 sur le premier niveau et 1 sur le deuxième niveau", "limite : le modèle place les électrons sur des trajets fixes, ce qui simplifie leur comportement réel"], "<b>Réponse modèle :</b> Le noyau, au centre, contient 3 protons et 4 neutrons. L'atome neutre compte 3 électrons : le premier niveau d'énergie, qui peut en contenir 2, est rempli, et le troisième électron occupe le deuxième niveau. Une limite du modèle de Bohr : il représente les électrons sur des trajets fixes et bien définis autour du noyau, alors que leur comportement réel ne se laisse pas décrire comme de simples orbites.<br><br><b>Points d'attribution :</b> 1 point pour le noyau correctement composé. 1 point pour la répartition 2 puis 1 des trois électrons. 1 point pour une limite pertinente du modèle.", {}); }
]), ["Pense à la structure de la réponse : une idée complète par point.", "Relis la question et vérifie que chaque partie demandée est traitée."]);
